        id: 'sh-16',
        status: 'In Progress',
        timestamp: '2026-10-06T06:00:00.000Z',
        updatedBy: 'Emergency Highway Patrol',
        notes: 'Temporary barricade placed.',
      },
      {
        id: 'sh-17',
